    lines = page.strip().split('\n')
    for line in lines:
        line_stripped = line.strip()
        if re.match(r'^(\\d+\\.?\\s+|References|Appendix|A\\b|B\\b|C\\b)', line_stripped) and len(line_stripped) < 100:
